# Attackers use homoglyphs (lookalike characters) to evade text filters.
# Defenders can NORMALISE text to undo this before detection.

import unicodedata

# VULNERABLE detector: checks raw text only
def naive_detect(text, banned):
    return any(word in text.lower() for word in banned)

# 'h\u0430te' uses a Cyrillic 'a' - looks identical, bypasses naive_detect

# SECURE detector: normalise + map homoglyphs first
def normalise(text):
    # NFKC collapses many lookalike/compatibility characters
    text = unicodedata.normalize("NFKC", text)
    # Map common homoglyphs back to ASCII
    homoglyphs = {"\u0430": "a", "\u0435": "e", "\u043e": "o"}
    for fake, real in homoglyphs.items():
        text = text.replace(fake, real)
    return text.lower()

def robust_detect(text, banned):
    clean = normalise(text)
    clean = clean.replace(" ", "").replace(".", "")  # undo spacing tricks
    return any(word in clean for word in banned)
